"""Private immutable scenario values; not an IPC contract or a writable store."""

import hashlib
import json
from dataclasses import asdict, dataclass, replace

SEMANTICS = "scenario-e2-v1"


def canonical(value: object) -> str:
    return json.dumps(
        value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
    )


def json_object(text: str) -> None:
    if not isinstance(text, str) or not isinstance(json.loads(text), dict):
        raise ValueError("Scenario payload must be a JSON object")
    canonical(json.loads(text))


def integer(value: int, minimum: int = 0) -> None:
    if type(value) is not int or value < minimum:
        raise ValueError("Invalid scenario integer")


@dataclass(frozen=True)
class Capacity:
    direct: int | None = None
    people: int | None = None
    per_person: int | None = None

    def __post_init__(self) -> None:
        direct = self.direct is not None
        product = self.people is not None and self.per_person is not None
        if direct == product or (
            direct and (self.people is not None or self.per_person is not None)
        ):
            raise ValueError("Choose exactly one capacity mode")
        for value in (self.direct, self.people, self.per_person):
            if value is not None:
                integer(value)

    @property
    def count(self) -> int:
        if self.direct is not None:
            return self.direct
        assert self.people is not None and self.per_person is not None
        return self.people * self.per_person


@dataclass(frozen=True)
class Event:
    id: str
    round: int
    sequence: int
    payload: str = "{}"

    def __post_init__(self) -> None:
        if not self.id:
            raise ValueError("Event ID required")
        integer(self.round, 1)
        integer(self.sequence)
        json_object(self.payload)


@dataclass(frozen=True)
class WorkOrder:
    id: str
    event_id: str
    created_round: int
    sequence: int
    status: str = "pending"

    def __post_init__(self) -> None:
        if not self.id or not self.event_id or self.status not in {"pending", "completed"}:
            raise ValueError("Invalid work order")
        integer(self.created_round)
        integer(self.sequence)


@dataclass(frozen=True)
class Alert:
    id: str
    severity: str
    status: str


@dataclass(frozen=True)
class State:
    orders: tuple[WorkOrder, ...] = ()
    alerts: tuple[Alert, ...] = ()
    assertions: str = "{}"
    order_sequence: int = 0
    created_orders: tuple[tuple[str, str, int], ...] = ()

    def __post_init__(self) -> None:
        json_object(self.assertions)
        if not isinstance(self.orders, tuple) or not isinstance(self.alerts, tuple):
            raise ValueError("State collections must be immutable tuples")
        integer(self.order_sequence)
        if not isinstance(self.created_orders, tuple):
            raise ValueError("Immutable order identity history required")
        ledger = {event: (identity, sequence) for event, identity, sequence in self.created_orders}
        if len(ledger) != len(self.created_orders):
            raise ValueError("Duplicate order creation event")
        for order in self.orders:
            entry = (order.id, order.sequence)
            if order.event_id in ledger and ledger[order.event_id] != entry:
                raise ValueError("Order creation identity changed")
            ledger[order.event_id] = entry
        if len({identity for identity, _ in ledger.values()}) != len(ledger):
            raise ValueError("Order ID reused by another event")
        for identity, sequence in ledger.values():
            if not identity:
                raise ValueError("Invalid historical order identity")
            integer(sequence)
        object.__setattr__(
            self,
            "created_orders",
            tuple((event, identity, sequence) for event, (identity, sequence) in ledger.items()),
        )
        object.__setattr__(
            self,
            "order_sequence",
            max(self.order_sequence, *(sequence for _, sequence in ledger.values()), 0),
        )
        for values in (self.orders, self.alerts):
            if len({item.id for item in values}) != len(values):
                raise ValueError("Duplicate scenario identity")


def create_order(state: State, event_id: str, round_number: int) -> State:
    """E.3 stable IDs, independent of run UUID; retries of an event are idempotent."""
    if any(event == event_id for event, _, _ in state.created_orders):
        return state
    sequence = state.order_sequence + 1
    identity = f"W{sequence:03}"
    if any(saved_id == identity for _, saved_id, _ in state.created_orders):
        raise ValueError("Work order identity collision")
    return replace(
        state, orders=(*state.orders, WorkOrder(identity, event_id, round_number, sequence))
    )


def resource_stage(state: State, capacity: Capacity) -> tuple[State, tuple[str, ...]]:
    queue = sorted(
        (order for order in state.orders if order.status != "completed"),
        key=lambda order: (order.created_round, order.sequence, order.id),
    )
    selected = tuple(order.id for order in queue[: capacity.count])
    identities = set(selected)
    return replace(
        state,
        orders=tuple(
            replace(order, status="completed") if order.id in identities else order
            for order in state.orders
        ),
    ), selected


@dataclass(frozen=True)
class Metrics:
    backlog: int
    completed: int
    open_high_alerts: int


def metrics(state: State, completed: tuple[str, ...]) -> Metrics:
    return Metrics(
        sum(order.status != "completed" for order in state.orders),
        len(set(completed)),
        sum(alert.severity == "High" and alert.status != "Closed" for alert in state.alerts),
    )


@dataclass(frozen=True)
class Definition:
    project_id: str
    engine_version: str
    dependency_lock_hash: str
    project_version: str
    scenario_id: str
    input_version: str
    rule_version: str
    behavior_version: str
    max_rounds: int
    capacity: Capacity
    events: tuple[Event, ...]
    initial: State = State()
    rules: str = "{}"
    behaviors: str = "{}"
    parameters: str = "{}"
    source: str = ""
    assumptions: tuple[str, ...] = ()
    semantics: str = SEMANTICS
    initial_consumed: tuple[str, ...] = ()

    def __post_init__(self) -> None:
        integer(self.max_rounds, 1)
        if self.max_rounds > 1000 or self.semantics != SEMANTICS:
            raise ValueError("Unsupported round limit or scenario semantics")
        if not all(
            (
                self.project_id,
                self.engine_version,
                self.dependency_lock_hash,
                self.project_version,
                self.scenario_id,
                self.input_version,
                self.rule_version,
                self.behavior_version,
            )
        ):
            raise ValueError("Scenario versions required")
        for text in (self.rules, self.behaviors, self.parameters):
            json_object(text)
        if not isinstance(self.events, tuple) or not isinstance(self.initial_consumed, tuple):
            raise ValueError("Immutable event inputs required")
        catalog = event_catalog(self.events)
        if len(set(self.initial_consumed)) != len(self.initial_consumed) or not set(
            self.initial_consumed
        ) <= set(catalog):
            raise ValueError("Invalid initial consumption")

    @property
    def digest(self) -> str:
        return hashlib.sha256(canonical(asdict(self)).encode()).hexdigest()


def event_catalog(events: tuple[Event, ...]) -> dict[str, Event]:
    catalog: dict[str, Event] = {}
    for event in events:
        if event.id in catalog and event != catalog[event.id]:
            raise ValueError("Event ID reused with different content")
        catalog.setdefault(event.id, event)
    return catalog


def copy_scenario(source: Definition, scenario_id: str, input_version: str) -> Definition:
    if scenario_id == source.scenario_id or not scenario_id or not input_version:
        raise ValueError("New scenario identity required")
    return replace(source, scenario_id=scenario_id, input_version=input_version)

"""E.2 orchestration only. Real inference/behavior/atomic storage are required ports.

This module performs no persistence and never registers a product capability.
Test ports are orchestration probes, not integrated domain execution evidence.
"""

from collections.abc import Callable
from dataclasses import dataclass
from typing import Protocol

from .model import (
    Definition,
    Event,
    Metrics,
    State,
    event_catalog,
    json_object,
    metrics,
    resource_stage,
)


class Cancelled(Exception):
    pass


class ScenarioFailure(Exception):
    """Restricted internal error; no source value/path/exception text is exposed."""

    def __init__(self, code: str) -> None:
        super().__init__(code)
        self.code = code


@dataclass(frozen=True)
class Context:
    round: int
    phase: str


@dataclass(frozen=True)
class Inference:
    input_state: State
    rule_version: str
    snapshot: str
    context: Context


@dataclass(frozen=True)
class Plan:
    action_count: int
    payload: str
    trace: tuple[tuple[str, str, int], ...]


@dataclass(frozen=True)
class Execution:
    state: State
    action_count: int
    generated: tuple[Event, ...] = ()


@dataclass(frozen=True)
class Checkpoint:
    definition_digest: str
    round: int
    state: State
    events: tuple[Event, ...]
    consumed: tuple[str, ...]
    completed: tuple[str, ...]


@dataclass(frozen=True)
class Round:
    checkpoint: Checkpoint
    input_events: tuple[str, ...]
    created: tuple[str, ...]
    resource_completed: tuple[str, ...]
    backlog: tuple[str, ...]
    metrics: Metrics
    before_inference: Inference
    end_inference: Inference
    trace: tuple[tuple[str, str, int], ...]
    frozen_plan: str


@dataclass(frozen=True)
class Result:
    definition: Definition
    status: str
    checkpoint: Checkpoint
    rounds: tuple[Round, ...]
    pending: tuple[Event, ...]
    error_code: str | None = None

    @property
    def has_unprocessed_events(self) -> bool:
        return bool(self.pending)


class Ports(Protocol):
    def apply_events(
        self, state: State, events: tuple[Event, ...], context: Context, check: Callable
    ) -> State: ...

    def infer(
        self, state: State, definition: Definition, context: Context, check: Callable
    ) -> Inference: ...

    def plan(
        self,
        state: State,
        inference: Inference,
        events: tuple[Event, ...],
        context: Context,
        check: Callable,
    ) -> Plan:
        """Freeze all conditions; validate conflicts and stable E.1 order before returning."""
        ...

    def execute(self, state: State, plan: Plan, context: Context, check: Callable) -> Execution:
        """Check cancellation between actions; perform exactly the frozen plan."""
        ...

    def commit(self, record: Round, check: Callable) -> None:
        """Owner atomically checks cancel/job identity and persists the full round.

        Return only after durable success. On uncertain acknowledgment reconcile by
        operationId; do not throw after a successful commit or replay side effects.
        """
        ...


def _inference(
    value: Inference, state: State, definition: Definition, context: Context
) -> Inference:
    if (
        value.input_state != state
        or value.rule_version != definition.rule_version
        or value.context != context
        or not value.snapshot
    ):
        raise ScenarioFailure("INFERENCE_IDENTITY")
    return value


def _initial(definition: Definition) -> Checkpoint:
    return Checkpoint(
        definition.digest,
        0,
        definition.initial,
        tuple(event_catalog(definition.events).values()),
        definition.initial_consumed,
        (),
    )


def _validate_resume(definition: Definition, checkpoint: Checkpoint) -> None:
    if checkpoint.definition_digest != definition.digest or type(checkpoint.round) is not int:
        raise ValueError("Snapshot belongs to another input/configuration")
    if not 0 <= checkpoint.round <= definition.max_rounds:
        raise ValueError("Invalid snapshot round")
    catalog = event_catalog(checkpoint.events)
    if not set(checkpoint.consumed) <= set(catalog) or len(set(checkpoint.consumed)) != len(
        checkpoint.consumed
    ):
        raise ValueError("Invalid snapshot consumption")
    for identity, event in event_catalog(definition.events).items():
        if catalog.get(identity) != event:
            raise ValueError("Snapshot input mismatch")
    initial = set(definition.initial_consumed)
    if any(
        catalog[identity].round > checkpoint.round
        for identity in set(checkpoint.consumed) - initial
    ):
        raise ValueError("Snapshot consumed a future event")
    if any(
        event.round <= checkpoint.round and event.id not in checkpoint.consumed
        for event in catalog.values()
    ):
        raise ValueError("Snapshot lost committed event consumption")
    if len(set(checkpoint.completed)) != len(checkpoint.completed):
        raise ValueError("Duplicate completion history")
    if not set(checkpoint.completed) <= {
        identity for _, identity, _ in checkpoint.state.created_orders
    }:
        raise ValueError("Unknown completed order")
    if not set(definition.initial_consumed) <= set(checkpoint.consumed):
        raise ValueError("Snapshot lost initial consumption")


def run(
    definition: Definition,
    ports: Ports,
    *,
    cancelled: Callable[[], bool] = lambda: False,
    resume: Checkpoint | None = None,
) -> Result:
    """Independent replay starts at original consumption; resume is always explicit.

    Each call needs a new persisted run/job from the owner. Resumed committed history
    belongs to the source run and is not copied or rewritten by this pure service.
    """
    checkpoint = resume if resume is not None else _initial(definition)
    _validate_resume(definition, checkpoint)
    history: list[Round] = []

    def check() -> None:
        if cancelled():
            raise Cancelled

    def result(status: str, code: str | None = None) -> Result:
        pending = tuple(
            event for event in checkpoint.events if event.id not in set(checkpoint.consumed)
        )
        return Result(definition, status, checkpoint, tuple(history), pending, code)

    try:
        check()
        # Even an empty initial scene must receive actual behavior-before inference.
        initial_context = Context(checkpoint.round, "initial")
        _inference(
            ports.infer(checkpoint.state, definition, initial_context, check),
            checkpoint.state,
            definition,
            initial_context,
        )
        check()
        for number in range(checkpoint.round + 1, definition.max_rounds + 1):
            catalog = event_catalog(checkpoint.events)
            events = tuple(
                sorted(
                    (
                        event
                        for event in catalog.values()
                        if event.round <= number and event.id not in set(checkpoint.consumed)
                    ),
                    key=lambda event: (event.sequence, event.id),
                )
            )
            check()
            applied = ports.apply_events(checkpoint.state, events, Context(number, "events"), check)
            check()
            before_context = Context(number, "before")
            before = _inference(
                ports.infer(applied, definition, before_context, check),
                applied,
                definition,
                before_context,
            )
            check()
            plan = ports.plan(applied, before, events, Context(number, "behavior"), check)
            if type(plan.action_count) is not int or not 0 <= plan.action_count <= 1000:
                raise ScenarioFailure("ACTION_LIMIT")
            json_object(plan.payload)
            if len(plan.trace) != plan.action_count or len(set(plan.trace)) != len(plan.trace):
                raise ScenarioFailure("ACTION_TRACE")
            for event_id, behavior_id, action_index in plan.trace:
                if (
                    event_id not in {event.id for event in events}
                    or not behavior_id
                    or type(action_index) is not int
                    or action_index < 1
                ):
                    raise ScenarioFailure("ACTION_TRACE")
            check()
            executed = ports.execute(applied, plan, Context(number, "behavior"), check)
            if type(executed.action_count) is not int or executed.action_count != plan.action_count:
                raise ScenarioFailure("ACTION_COUNT")
            check()
            for event in executed.generated:
                if event.round != number + 1:
                    raise ScenarioFailure("GENERATED_EVENT_ROUND")
            # Keep the complete catalog, including consumed payloads, to detect ID reuse.
            combined = event_catalog((*checkpoint.events, *executed.generated))
            state, completed_now = resource_stage(executed.state, definition.capacity)
            check()
            end_context = Context(number, "end")
            end = _inference(
                ports.infer(state, definition, end_context, check), state, definition, end_context
            )
            check()
            previous_completed = {o.id for o in checkpoint.state.orders if o.status == "completed"}
            completed = tuple(
                dict.fromkeys(
                    (
                        *checkpoint.completed,
                        *(
                            o.id
                            for o in state.orders
                            if o.status == "completed" and o.id not in previous_completed
                        ),
                    )
                )
            )
            next_checkpoint = Checkpoint(
                definition.digest,
                number,
                state,
                tuple(combined.values()),
                (*checkpoint.consumed, *(event.id for event in events)),
                completed,
            )
            old_ids = {o.id for o in checkpoint.state.orders}
            backlog = tuple(
                o.id
                for o in sorted(state.orders, key=lambda o: (o.created_round, o.sequence, o.id))
                if o.status != "completed"
            )
            record = Round(
                next_checkpoint,
                tuple(event.id for event in events),
                tuple(o.id for o in state.orders if o.id not in old_ids),
                completed_now,
                backlog,
                metrics(state, completed),
                before,
                end,
                plan.trace,
                plan.payload,
            )
            check()
            ports.commit(record, check)
            # No cancellation checkpoint here: a durable commit must stay visible.
            checkpoint = next_checkpoint
            history.append(record)
        check()
        return result("succeeded")
    except Cancelled:
        return result("cancelled")
    except ScenarioFailure as error:
        return result("failed", error.code)
    except Exception:
        return result("failed", "SCENARIO_STAGE_FAILED")

/** Private view values. Public bridge validation belongs to the sole contracts owner. */
export interface ScenarioIdentity {
  projectId: string
  engineVersion: string
  dependencyLockHash: string
  projectVersion: string
  scenarioId: string
  inputVersion: string
  ruleVersion: string
  behaviorVersion: string
  configurationDigest: string
  semantics: string
}

export interface MetricValues {
  backlog: number
  completed: number
  openHighAlerts: number
}

export interface RoundView {
  number: number
  created: readonly string[]
  completed: readonly string[]
  backlog: readonly string[]
  metrics: MetricValues
  inputEvents: readonly string[]
  behaviorTrace: readonly string[]
  beforeInference: string
  endInference: string
}

export interface RunView {
  id: string
  identity: ScenarioIdentity
  status: 'queued' | 'running' | 'cancelling' | 'cancelled' | 'succeeded' | 'failed'
  rounds: readonly RoundView[]
  pendingEvents: readonly string[]
  evidence: {
    source: string
    assumptions: readonly string[]
    maxRounds: number
    capacity: number
    parameters: string
  }
  replayAvailable: boolean
  replayUnavailableReason?: string
  errorMessage?: string
}

export interface ScenarioView {
  identity: ScenarioIdentity
  name: string
  maxRounds: number
  capacity: number
  source: string
  assumptions: readonly string[]
  runs: readonly RunView[]
}

export interface ScenarioInputDraft {
  initialState: string
  events: string
  rules: string
  behaviors: string
  parameters: string
  assumptions: string
  source: string
}

export interface ScenarioDraft {
  name: string
  maxRounds: number
  capacity: number
  capacityMode?: 'direct' | 'people'
  people?: number
  perPerson?: number
  inputs?: ScenarioInputDraft
}

export function validInputs(inputs: ScenarioInputDraft): boolean {
  try {
    for (const value of [inputs.initialState, inputs.rules, inputs.behaviors, inputs.parameters]) {
      const parsed: unknown = JSON.parse(value)
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return false
    }
    const events: unknown = JSON.parse(inputs.events)
    if (!Array.isArray(events)) return false
    const catalog = new Map<string, string>()
    for (const event of events) {
      if (!event || typeof event !== 'object' || Array.isArray(event)) return false
      const item = event as Record<string, unknown>
      if (Object.keys(item).some((key) => !['id', 'round', 'sequence', 'payload'].includes(key)))
        return false
      if (
        typeof item.id !== 'string' ||
        !item.id ||
        !Number.isSafeInteger(item.round) ||
        (item.round as number) < 1 ||
        !Number.isSafeInteger(item.sequence) ||
        (item.sequence as number) < 0
      )
        return false
      if (!item.payload || typeof item.payload !== 'object' || Array.isArray(item.payload))
        return false
      const serialized = JSON.stringify([item.round, item.sequence, item.payload])
      if (catalog.has(item.id) && catalog.get(item.id) !== serialized) return false
      catalog.set(item.id, serialized)
    }
    return true
  } catch {
    return false
  }
}

export const metricDefinitions = [
  ['工单积压', '提交时状态不为“已完成”的工单总数，单位：单。'],
  ['累计完成', '从本次运行开始，累计变为“已完成”的工单数，单位：单。'],
  ['未闭环高危告警', '提交时等级为 High 且告警状态不为 Closed 的告警数，单位：条。'],
] as const

export function sameInput(a: ScenarioIdentity, b: ScenarioIdentity): boolean {
  return (
    a.projectId === b.projectId &&
    a.engineVersion === b.engineVersion &&
    a.dependencyLockHash === b.dependencyLockHash &&
    a.projectVersion === b.projectVersion &&
    a.scenarioId === b.scenarioId &&
    a.inputVersion === b.inputVersion &&
    a.ruleVersion === b.ruleVersion &&
    a.behaviorVersion === b.behaviorVersion &&
    a.configurationDigest === b.configurationDigest &&
    a.semantics === b.semantics
  )
}

export function resultLabel(run: RunView, current: ScenarioIdentity): string {
  const statuses = {
    queued: '排队中',
    running: '运行中',
    cancelling: '取消中',
    cancelled: '已取消 · 历史运行',
    failed: '失败 · 历史运行',
    succeeded: '成功',
  }
  if (run.status !== 'succeeded') return statuses[run.status]
  return sameInput(run.identity, current) ? '当前结果' : '历史结果 · 输入版本已变化'
}

export function completionLabel(run: RunView): string {
  if (run.pendingEvents.length > 0) return `存在未处理事件（${run.pendingEvents.length}）`
  if (run.status === 'succeeded') return '已配置轮次执行完毕，无未处理事件'
  return '运行尚未成功结束'
}

export function validDraft(draft: ScenarioDraft): boolean {
  return (
    draft.name.trim().length > 0 &&
    Number.isSafeInteger(draft.maxRounds) &&
    draft.maxRounds >= 1 &&
    draft.maxRounds <= 1000 &&
    Number.isSafeInteger(draft.capacity) &&
    draft.capacity >= 0 &&
    (draft.capacityMode !== 'people' ||
      (Number.isSafeInteger(draft.people) &&
        draft.people! >= 0 &&
        Number.isSafeInteger(draft.perPerson) &&
        draft.perPerson! >= 0 &&
        Number.isSafeInteger(draft.people! * draft.perPerson!))) &&
    (!draft.inputs || validInputs(draft.inputs))
  )
}

export interface ComparisonRow {
  round: number
  values: readonly (MetricValues | null)[]
}

export function compareRuns(runs: readonly RunView[]): readonly ComparisonRow[] {
  if (runs.length < 2 || runs.some((run) => run.status !== 'succeeded')) return []
  const rounds = [...new Set(runs.flatMap((run) => run.rounds.map((round) => round.number)))].sort(
    (a, b) => a - b,
  )
  return rounds.map((round) => ({
    round,
    values: runs.map((run) => run.rounds.find((item) => item.number === round)?.metrics ?? null),
  }))
}

import { useState } from 'react'
import type { ScenarioDraft, ScenarioView, RunView } from './presentation'
import {
  compareRuns,
  completionLabel,
  metricDefinitions,
  resultLabel,
  validDraft,
  type ScenarioInputDraft,
} from './presentation'
import './scenario.css'

/** Callbacks are supplied only by approved business adapters; never a generic invoke channel. */
export interface ScenarioActions {
  create?: (draft: ScenarioDraft, sourceScenarioId?: string) => Promise<void>
  run?: (scenarioId: string, inputVersion: string) => Promise<void>
  cancel?: (runId: string) => Promise<void>
  replay?: (runId: string) => Promise<void>
  resume?: (runId: string, round: number) => Promise<void>
  restore?: (scenarioId: string) => Promise<void>
  deleteRun?: (runId: string) => Promise<void>
}

export function ScenarioPage({
  scenarios,
  actions,
  unavailableReason,
}: {
  scenarios: readonly ScenarioView[]
  actions: ScenarioActions
  unavailableReason?: string
}) {
  const [selected, setSelected] = useState('')
  const [sourceMode, setSourceMode] = useState<'project' | 'scenario'>('scenario')
  const [compared, setCompared] = useState<readonly string[]>([])
  const [draft, setDraft] = useState<ScenarioDraft>({ name: '', maxRounds: 4, capacity: 3 })
  const [inputs, setInputs] = useState<ScenarioInputDraft | null>(null)
  const [message, setMessage] = useState('')
  const [busy, setBusy] = useState(false)
  const current = scenarios.find((item) => item.identity.scenarioId === selected) ?? scenarios[0]
  const copySource = sourceMode === 'scenario' ? current?.identity.scenarioId : undefined
  const configuredDraft: ScenarioDraft = {
    ...draft,
    capacity:
      draft.capacityMode === 'people'
        ? (draft.people ?? NaN) * (draft.perPerson ?? NaN)
        : draft.capacity,
    ...(inputs ? { inputs } : {}),
  }
  const run = current?.runs.at(-1)
  const active = run && ['queued', 'running', 'cancelling'].includes(run.status)
  const comparison = scenarios
    .filter((item) => compared.includes(item.identity.scenarioId))
    .map((item) => ({ scenario: item, run: item.runs.at(-1) }))
  const comparisonRuns = comparison.flatMap((item) => (item.run ? [item.run] : []))
  const rows = comparisonRuns.length === comparison.length ? compareRuns(comparisonRuns) : []

  async function perform(action: () => Promise<void>) {
    if (busy) return
    setBusy(true)
    setMessage('')
    try {
      await action()
    } catch {
      setMessage('操作未完成。请查看任务状态和最后已提交轮次后重试。')
    } finally {
      setBusy(false)
    }
  }

  function runButton(label: string, enabled: boolean, action: () => Promise<void>) {
    return (
      <button type="button" disabled={busy || !enabled} onClick={() => void perform(action)}>
        {label}
      </button>
    )
  }

  return (
    <main className="scenario-page" aria-busy={busy}>
      <header className="scenario-heading">
        <div>
          <p className="scenario-kicker">固定轮次情景推演</p>
          <h1>沙盘</h1>
          <p>复制场景，改变资源假设，再对照每一轮的真实运行记录。</p>
        </div>
        <p className="scenario-notice">推演基于选定输入和假设，不代表无条件的事实预测。</p>
      </header>
      {unavailableReason && <p role="status">{unavailableReason}</p>}
      {message && <p role="alert">{message}</p>}
      <section className="scenario-panel" aria-labelledby="scenario-create">
        <h2 id="scenario-create">创建或复制场景</h2>
        <form
          onSubmit={(event) => {
            event.preventDefault()
            if (validDraft(configuredDraft) && actions.create)
              void perform(() => actions.create!(configuredDraft, copySource))
          }}
        >
          <label>
            创建来源
            <select
              aria-label="创建来源"
              value={copySource ? 'scenario' : 'project'}
              onChange={(event) => setSourceMode(event.target.value as 'project' | 'scenario')}
            >
              <option value="project">基准项目</option>
              <option value="scenario" disabled={!current}>
                选中场景
              </option>
            </select>
          </label>
          <label>
            场景名称
            <input
              required
              value={draft.name}
              onChange={(event) => setDraft({ ...draft, name: event.target.value })}
            />
          </label>
          <label>
            最大轮数（1–1000）
            <input
              type="number"
              min="1"
              max="1000"
              step="1"
              required
              value={draft.maxRounds}
              onChange={(event) => setDraft({ ...draft, maxRounds: event.target.valueAsNumber })}
            />
          </label>
          <label>
            每轮处理产能（单）
            <input
              type="number"
              min="0"
              step="1"
              required
              value={draft.capacity}
              disabled={draft.capacityMode === 'people'}
              onChange={(event) => setDraft({ ...draft, capacity: event.target.valueAsNumber })}
            />
          </label>
          <label>
            产能输入方式
            <select
              aria-label="产能输入方式"
              value={draft.capacityMode ?? 'direct'}
              onChange={(event) =>
                setDraft({
                  ...draft,
                  capacityMode: event.target.value as 'direct' | 'people',
                  people: 1,
                  perPerson: 3,
                })
              }
            >
              <option value="direct">直接设置每轮产能</option>
              <option value="people">人数 × 每人每轮处理数</option>
            </select>
          </label>
          {draft.capacityMode === 'people' && (
            <>
              <label>
                人员数
                <input
                  type="number"
                  min="0"
                  step="1"
                  value={draft.people}
                  onChange={(event) => setDraft({ ...draft, people: event.target.valueAsNumber })}
                />
              </label>
              <label>
                每人每轮处理数
                <input
                  type="number"
                  min="0"
                  step="1"
                  value={draft.perPerson}
                  onChange={(event) =>
                    setDraft({ ...draft, perPerson: event.target.valueAsNumber })
                  }
                />
              </label>
            </>
          )}
          <button type="submit" disabled={busy || !actions.create || !validDraft(configuredDraft)}>
            {copySource ? '复制选中场景' : '从项目创建场景'}
          </button>
        </form>
        <p>初始状态、事件、行为和规则从所选来源复制；运行记录不会被复制为新场景结果。</p>
        <details>
          <summary>配置场景输入、规则、事件与业务参数</summary>
          <p>
            默认沿用来源场景。需要自定义时，编辑结构化内容；行为条件和规则内容仍按相应模块的支持范围校验。
          </p>
          <label>
            <input
              type="checkbox"
              checked={inputs !== null}
              onChange={(event) =>
                setInputs(
                  event.target.checked
                    ? {
                        initialState: '{}',
                        events: '[]',
                        rules: '{}',
                        behaviors: '{}',
                        parameters: '{}',
                        assumptions: '',
                        source: '',
                      }
                    : null,
                )
              }
            />
            自定义输入（替换复制的输入）
          </label>
          {inputs && (
            <div className="scenario-inputs">
              {(
                [
                  ['initialState', '初始状态（对象）'],
                  ['events', '逐轮事件（列表，含 id、round、sequence、payload）'],
                  ['rules', '启用规则与版本（对象）'],
                  ['behaviors', '启用行为与版本（对象）'],
                  ['parameters', '业务参数（对象）'],
                  ['assumptions', '主要假设'],
                  ['source', '数据来源'],
                ] as const
              ).map(([key, label]) => (
                <label key={key}>
                  {label}
                  <textarea
                    aria-label={label}
                    rows={3}
                    value={inputs[key]}
                    onChange={(event) => setInputs({ ...inputs, [key]: event.target.value })}
                  />
                </label>
              ))}
            </div>
          )}
          {inputs && !validDraft(configuredDraft) && (
            <p role="status">请检查结构化输入格式、事件身份、轮次与产能；当前配置尚不能提交。</p>
          )}
          <p>观察指标：工单积压、累计完成、未闭环高危告警。每轮与期末均保留，定义见下方。</p>
        </details>
      </section>
      <div className="scenario-layout">
        <section className="scenario-panel" aria-labelledby="scenario-list">
          <h2 id="scenario-list">场景与对比</h2>
          {scenarios.length === 0 && <p>尚无场景。接通项目服务后，可从当前已提交项目创建。</p>}
          {scenarios.map((scenario) => (
            <div className="scenario-choice" key={scenario.identity.scenarioId}>
              <button
                type="button"
                aria-pressed={current?.identity.scenarioId === scenario.identity.scenarioId}
                onClick={() => setSelected(scenario.identity.scenarioId)}
              >
                {scenario.name}
                <small>
                  {scenario.maxRounds} 轮 · 产能 {scenario.capacity} 单/轮
                </small>
              </button>
              <label>
                <input
                  type="checkbox"
                  checked={compared.includes(scenario.identity.scenarioId)}
                  onChange={(event) =>
                    setCompared(
                      event.target.checked
                        ? [...compared, scenario.identity.scenarioId]
                        : compared.filter((id) => id !== scenario.identity.scenarioId),
                    )
                  }
                />
                加入对比：{scenario.name}
              </label>
            </div>
          ))}
        </section>
        <section className="scenario-panel" aria-labelledby="scenario-details">
          <h2 id="scenario-details">{current?.name ?? '运行详情'}</h2>
          {current && (
            <>
              <p>
                项目 {current.identity.projectId} / {current.identity.projectVersion} · 输入{' '}
                {current.identity.inputVersion}
              </p>
              <p>
                规则 {current.identity.ruleVersion} · 行为 {current.identity.behaviorVersion} · 语义{' '}
                {current.identity.semantics}
              </p>
              <p>数据来源：{current.source || '未记录'}</p>
              <ul>
                {current.assumptions.map((text, index) => (
                  <li key={index}>{text}</li>
                ))}
              </ul>
              <div className="scenario-actions">
                {runButton('运行场景', !!actions.run && !active, () =>
                  actions.run!(current.identity.scenarioId, current.identity.inputVersion),
                )}
                {runButton('恢复基准场景', !!actions.restore && !active, () =>
                  actions.restore!(current.identity.scenarioId),
                )}
                {run &&
                  runButton(
                    '取消运行',
                    !!actions.cancel && !!active && run.status !== 'cancelling',
                    () => actions.cancel!(run.id),
                  )}
              </div>
              {run ? (
                <RunDetails
                  run={run}
                  scenario={current}
                  actions={actions}
                  busy={busy}
                  perform={perform}
                />
              ) : (
                <p>还没有运行记录。运行后显示逐轮状态、指标和依据。</p>
              )}
              {current.runs.length > 1 && (
                <details>
                  <summary>历史运行（{current.runs.length - 1}）</summary>
                  {current.runs.slice(0, -1).map((history) => (
                    <RunDetails
                      key={history.id}
                      run={history}
                      scenario={current}
                      actions={actions}
                      busy={busy}
                      perform={perform}
                    />
                  ))}
                </details>
              )}
            </>
          )}
        </section>
      </div>
      <section className="scenario-panel" aria-labelledby="scenario-compare">
        <h2 id="scenario-compare">逐轮与最终指标对比</h2>
        {rows.length === 0 ? (
          <p>选择至少两个已有成功运行的场景。失败或尚未完成的运行不能作为成功结果对比。</p>
        ) : (
          <>
            <div className="scenario-table-scroll">
              <table>
                <caption>
                  每格依次为积压 / 累计完成 / 未闭环高危告警；最后一行为各场景该轮指标。
                </caption>
                <thead>
                  <tr>
                    <th scope="col">轮次</th>
                    {comparison.map(({ scenario, run: item }) => (
                      <th scope="col" key={scenario.identity.scenarioId}>
                        {scenario.name}
                        <small>
                          {item && resultLabel(item, scenario.identity)} ·{' '}
                          {item?.identity.inputVersion}
                        </small>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {rows.map((row) => (
                    <tr key={row.round}>
                      <th scope="row">{row.round}</th>
                      {row.values.map((value, index) => (
                        <td key={comparison[index].scenario.identity.scenarioId}>
                          {value
                            ? `${value.backlog} / ${value.completed} / ${value.openHighAlerts}`
                            : '无该轮记录'}
                        </td>
                      ))}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            <h3>各场景最终已提交指标</h3>
            <ul>
              {comparison.map(({ scenario, run: item }) => {
                const final = item?.rounds.at(-1)
                return (
                  <li key={scenario.identity.scenarioId}>
                    {scenario.name}：
                    {final
                      ? `第 ${final.number} 轮 · 积压 ${final.metrics.backlog} 单 · 累计完成 ${final.metrics.completed} 单 · 未闭环高危 ${final.metrics.openHighAlerts} 条`
                      : '没有已提交轮次'}
                  </li>
                )
              })}
            </ul>
            <ul>
              {comparison.map(({ scenario, run: item }) => (
                <li key={scenario.identity.scenarioId}>
                  {scenario.name}：{item && completionLabel(item)}
                </li>
              ))}
            </ul>
          </>
        )}
        <dl>
          {metricDefinitions.map(([name, formula]) => (
            <div key={name}>
              <dt>{name}</dt>
              <dd>{formula}</dd>
            </div>
          ))}
        </dl>
      </section>
    </main>
  )
}

function RunDetails({
  run,
  scenario,
  actions,
  busy,
  perform,
}: {
  run: RunView
  scenario: ScenarioView
  actions: ScenarioActions
  busy: boolean
  perform: (action: () => Promise<void>) => Promise<void>
}) {
  const terminal = ['succeeded', 'failed', 'cancelled'].includes(run.status)
  const last = run.rounds.at(-1)
  return (
    <article className="scenario-run">
      <h3>{resultLabel(run, scenario.identity)}</h3>
      <p>
        运行 {run.id} · 输入 {run.identity.inputVersion} · 最后已提交轮次 {last?.number ?? 0}
      </p>
      <p>
        项目 {run.identity.projectId} / {run.identity.projectVersion} · 规则{' '}
        {run.identity.ruleVersion} · 行为 {run.identity.behaviorVersion} · 语义{' '}
        {run.identity.semantics}
      </p>
      <p>
        引擎 {run.identity.engineVersion} · 依赖锁 {run.identity.dependencyLockHash}
      </p>
      <p>
        本次运行参数：最多 {run.evidence.maxRounds} 轮 · 产能 {run.evidence.capacity} 单/轮 ·{' '}
        {run.evidence.parameters}
      </p>
      <p>本次运行来源：{run.evidence.source || '未记录'}</p>
      <ul>
        {run.evidence.assumptions.map((text, index) => (
          <li key={index}>{text}</li>
        ))}
      </ul>
      <p role="status">{completionLabel(run)}</p>
      {run.errorMessage && <p role="alert">{run.errorMessage}</p>}
      {run.pendingEvents.length > 0 && (
        <details>
          <summary>未处理事件</summary>
          <p>{run.pendingEvents.join('、')}</p>
        </details>
      )}
      <p>
        {run.replayAvailable
          ? '重放所需记录已齐全'
          : `不可重放：${run.replayUnavailableReason || '输入或执行版本记录尚未齐全'}`}
      </p>
      <div className="scenario-actions">
        <button
          type="button"
          disabled={busy || !terminal || !run.replayAvailable || !actions.replay}
          onClick={() => void perform(() => actions.replay!(run.id))}
        >
          独立重放（从初始消费状态）
        </button>
        <button
          type="button"
          disabled={busy || !terminal || !last || !actions.resume}
          onClick={() => void perform(() => actions.resume!(run.id, last!.number))}
        >
          显式从最后快照续跑
        </button>
        <button
          type="button"
          disabled={busy || !terminal || !actions.deleteRun}
          onClick={() => void perform(() => actions.deleteRun!(run.id))}
        >
          删除此运行记录
        </button>
      </div>
      {run.rounds.map((round) => (
        <details key={round.number}>
          <summary>
            第 {round.number} 轮 · 积压 {round.metrics.backlog} 单 · 累计完成{' '}
            {round.metrics.completed} 单 · 未闭环高危 {round.metrics.openHighAlerts} 条
          </summary>
          <dl>
            <dt>输入事件</dt>
            <dd>{round.inputEvents.join('、') || '无'}</dd>
            <dt>本轮创建</dt>
            <dd>{round.created.join('、') || '无'}</dd>
            <dt>资源阶段完成</dt>
            <dd>{round.completed.join('、') || '无'}</dd>
            <dt>轮末积压（处理队列顺序）</dt>
            <dd>{round.backlog.join('、') || '无'}</dd>
            <dt>行为前推理</dt>
            <dd>{round.beforeInference}</dd>
            <dt>行为执行顺序</dt>
            <dd>{round.behaviorTrace.join(' → ') || '无触发'}</dd>
            <dt>轮末推理</dt>
            <dd>{round.endInference}</dd>
          </dl>
          <button
            type="button"
            disabled={busy || !terminal || !actions.resume}
            onClick={() => void perform(() => actions.resume!(run.id, round.number))}
          >
            显式从第 {round.number} 轮快照创建续跑
          </button>
        </details>
      ))}
    </article>
  )
}

import { describe, expect, it } from 'vitest'
import {
  compareRuns,
  completionLabel,
  resultLabel,
  sameInput,
  validDraft,
  type RunView,
  type ScenarioIdentity,
} from '../../apps/desktop/src/renderer/src/scenario/presentation'

const identity: ScenarioIdentity = {
  projectId: 'project-1',
  engineVersion: 'engine-1',
  dependencyLockHash: 'lock-1',
  projectVersion: 'P1',
  scenarioId: 'S1',
  inputVersion: 'V1',
  ruleVersion: 'R1',
  behaviorVersion: 'B1',
  configurationDigest: 'C1',
  semantics: 'scenario-e2-v1',
}
const run: RunView = {
  id: 'run1',
  identity,
  status: 'succeeded',
  rounds: [
    {
      number: 1,
      created: ['W001'],
      completed: [],
      backlog: ['W001'],
      metrics: { backlog: 1, completed: 0, openHighAlerts: 1 },
      inputEvents: ['E1'],
      behaviorTrace: ['E1/B1'],
      beforeInference: 'before1',
      endInference: 'end1',
    },
  ],
  pendingEvents: [],
  replayAvailable: false,
  evidence: {
    source: 'probe',
    assumptions: ['original V1 assumption'],
    maxRounds: 4,
    capacity: 3,
    parameters: '{}',
  },
}

describe('T07 scenario presentation identity and truthful states', () => {
  it('never promotes a V1 late completion as the current V2 result', () => {
    expect(resultLabel(run, { ...identity, inputVersion: 'V2' })).toContain('历史结果')
    expect(resultLabel(run, identity)).toBe('当前结果')
  })
  it.each(Object.keys(identity) as (keyof ScenarioIdentity)[])(
    'checks the complete dependency identity: %s',
    (key) => expect(sameInput(identity, { ...identity, [key]: 'changed' })).toBe(false),
  )
  it('preserves cancellation and failure labels even when input matches', () => {
    expect(resultLabel({ ...run, status: 'cancelled' }, identity)).toBe('已取消 · 历史运行')
    expect(resultLabel({ ...run, status: 'failed' }, identity)).toBe('失败 · 历史运行')
    expect(completionLabel({ ...run, status: 'failed' })).toBe('运行尚未成功结束')
  })
  it('maximum-round success still exposes all unprocessed events', () => {
    expect(completionLabel({ ...run, pendingEvents: ['E2', 'E3'] })).toBe('存在未处理事件（2）')
    expect(completionLabel(run)).toBe('已配置轮次执行完毕，无未处理事件')
  })
  it.each([0, 1001, 1.5, NaN, Infinity])('rejects invalid maxRounds %s', (maxRounds) => {
    expect(validDraft({ name: '基准', maxRounds, capacity: 3 })).toBe(false)
  })
  it.each([-1, 1.5, NaN, Infinity])('rejects invalid capacity %s', (capacity) => {
    expect(validDraft({ name: '基准', maxRounds: 4, capacity })).toBe(false)
  })
  it('allows zero capacity and the full 1000 round boundary', () => {
    expect(validDraft({ name: '资源不足场景', maxRounds: 1000, capacity: 0 })).toBe(true)
    expect(validDraft({ name: ' ', maxRounds: 4, capacity: 3 })).toBe(false)
  })
  it('compares real round values without inventing missing observations', () => {
    const second: RunView = {
      ...run,
      id: 'run2',
      identity: { ...identity, scenarioId: 'S2' },
      rounds: [
        { ...run.rounds[0], number: 2, metrics: { backlog: 0, completed: 4, openHighAlerts: 0 } },
      ],
    }
    expect(compareRuns([run, second])).toEqual([
      { round: 1, values: [{ backlog: 1, completed: 0, openHighAlerts: 1 }, null] },
      { round: 2, values: [null, { backlog: 0, completed: 4, openHighAlerts: 0 }] },
    ])
    expect(compareRuns([run])).toEqual([])
    expect(compareRuns([run, { ...second, status: 'failed' }])).toEqual([])
  })
})

describe('T07 structured local draft checks', () => {
  const inputs = {
    initialState: '{}',
    events: '[]',
    rules: '{}',
    behaviors: '{}',
    parameters: '{}',
    assumptions: '假设',
    source: '来源',
  }
  const draft = { name: '自定义', maxRounds: 4, capacity: 3, inputs }
  it('validates events with identity/round/sequence/object payload before submission', () => {
    expect(
      validDraft({
        ...draft,
        inputs: { ...inputs, events: '[{"id":"E1","round":1,"sequence":0,"payload":{}}]' },
      }),
    ).toBe(true)
    for (const events of [
      '{}',
      '[{}]',
      '[{"id":"E1","round":0,"sequence":0,"payload":{}}]',
      '[{"id":"E1","round":1,"sequence":0,"payload":"code"}]',
      '[{"id":"E1","round":1,"sequence":0,"payload":{},"unknown":1}]',
    ]) {
      expect(validDraft({ ...draft, inputs: { ...inputs, events } })).toBe(false)
    }
    expect(validDraft({ ...draft, inputs: { ...inputs, rules: 'null' } })).toBe(false)
    expect(validDraft({ ...draft, inputs: { ...inputs, initialState: '[]' } })).toBe(false)
  })
  it('rejects reused event IDs with different content', () => {
    expect(
      validDraft({
        ...draft,
        inputs: {
          ...inputs,
          events:
            '[{"id":"E1","round":1,"sequence":0,"payload":{}},{"id":"E1","round":2,"sequence":1,"payload":{}}]',
        },
      }),
    ).toBe(false)
  })
  it('validates personnel capacity and safe integer bounds', () => {
    expect(validDraft({ ...draft, capacityMode: 'people', people: 2, perPerson: 3 })).toBe(true)
    expect(validDraft({ ...draft, capacityMode: 'people', people: 2 })).toBe(false)
    expect(
      validDraft({
        ...draft,
        capacityMode: 'people',
        people: Number.MAX_SAFE_INTEGER,
        perPerson: 3,
      }),
    ).toBe(false)
  })
})

